param([Parameter(Mandatory)][string]$OutputPath,[string]$PlanPath=(Join-Path $PSScriptRoot 'exception-data-floating-key-equality-plan-v1.json'))
$ErrorActionPreference='Stop';Set-StrictMode -Version Latest
$coreHash=(Get-FileHash -LiteralPath ([object].Assembly.Location) -Algorithm SHA256).Hash.ToLowerInvariant();if([Environment]::Version.ToString() -ne '10.0.12' -or $coreHash -ne '1125acc8106c43fc8bad2d203c4c4485df6182d292846c2fff415c1040c54678'){throw 'Pinned CoreLib required'}
[Globalization.CultureInfo]::CurrentCulture=[Globalization.CultureInfo]::InvariantCulture;[Globalization.CultureInfo]::CurrentUICulture=[Globalization.CultureInfo]::InvariantCulture
function Key($Spec){if($Spec.kind -eq 'float'){$k=[BitConverter]::Int32BitsToSingle([Convert]::ToInt32($Spec.bits,16))}else{$k=[BitConverter]::Int64BitsToDouble([Convert]::ToInt64($Spec.bits,16))};return $k}
function Dict($D,[string]$Method,[object[]]$Arguments){$owner=if($Method -eq 'get_Count'){[Collections.ICollection]}else{[Collections.IDictionary]};$r=$owner.GetMethod($Method).Invoke($D,$Arguments);return ,$r}
function Cursor($C,[string]$Method){$owner=if($Method -in @('get_Key','get_Value','get_Entry')){[Collections.IDictionaryEnumerator]}else{[Collections.IEnumerator]};$r=$owner.GetMethod($Method).Invoke($C,[object[]]@());return ,$r}
function ViewCursor($C){$r=[Collections.IEnumerable].GetMethod('GetEnumerator').Invoke($C,[object[]]@());return ,$r}
function Failure($Record){$e=$Record.Exception;while($e -is [Reflection.TargetInvocationException] -or $e -is [Management.Automation.MethodInvocationException]){$e=$e.InnerException};return [ordered]@{ok=$false;exception=$e.GetType().FullName;messageUnits=[int[]][char[]]$e.Message;hResult=$e.HResult;paramName=$(if($e -is [ArgumentException]){$e.ParamName}else{$null})}}
function Outcome([scriptblock]$Action,[string]$Kind){try{$v=&$Action;return [ordered]@{ok=$true;kind=$Kind;value=$(if($Kind -eq 'void'){$null}else{$v})}}catch{return Failure $_}}
function Normal($V){if([object]::ReferenceEquals($V,$null)){return '~'};if($V -is [Collections.DictionaryEntry]){return 'E'+(Normal $V.Key)+'='+$V.Value};if($V -is [single]){return 'F'+[BitConverter]::SingleToInt32Bits($V).ToString('x8')};if($V -is [double]){return 'D'+[BitConverter]::DoubleToInt64Bits($V).ToString('x16')};return 'V'+$V}
function Current($C){try{return [ordered]@{ok=$true;kind='current';value=(Normal (Cursor $C 'get_Current'))}}catch{return Failure $_}}
function Contents($D){$c=Dict $D 'GetEnumerator' ([object[]]@());$items=@();while(Cursor $c 'MoveNext'){$items+=@(Normal (Cursor $c 'get_Entry'))};return ,$items}
$plan=Get-Content -LiteralPath $PlanPath -Raw|ConvertFrom-Json;$profiles=[Collections.Generic.List[object]]::new();$calls=0
for($s=0;$s -lt $plan.profiles.Count;$s++){for($q=0;$q -lt $plan.profiles.Count;$q++){
 $stored=Key $plan.profiles[$s];$query=Key $plan.profiles[$q];$storedTag=$(if($plan.profiles[$s].kind -eq 'float'){'F'}else{'D'})+$plan.profiles[$s].bits;$queryTag=$(if($plan.profiles[$q].kind -eq 'float'){'F'}else{'D'})+$plan.profiles[$q].bits;if((Normal $stored) -ne $storedTag -or (Normal $query) -ne $queryTag){throw 'Native raw key transport changed'}
 $d=[Exception]::new('floating equality').Data;$initial=Outcome {Dict $d 'Add' ([object[]]@($stored,'initial'))} 'void';$steps=@()
 foreach($operation in @('read','contains','write','add','remove','clear','clearEmpty','removeEmpty')){$cursors=@((Dict $d 'GetEnumerator' ([object[]]@())),(ViewCursor (Dict $d 'get_Keys' ([object[]]@()))),(ViewCursor (Dict $d 'get_Values' ([object[]]@()))));$before=@();foreach($c in $cursors){$before+=@(Outcome {Cursor $c 'MoveNext'} 'bool')};$result=switch($operation){'read'{Outcome {Dict $d 'get_Item' ([object[]]@($query))} 'value'};'contains'{Outcome {Dict $d 'Contains' ([object[]]@($query))} 'bool'};'write'{Outcome {Dict $d 'set_Item' ([object[]]@($query,'updated'))} 'void'};'add'{Outcome {Dict $d 'Add' ([object[]]@($query,'added'))} 'void'};'remove'{Outcome {Dict $d 'Remove' ([object[]]@($query))} 'void'};'clear'{Outcome {Dict $d 'Clear' ([object[]]@())} 'void'};'clearEmpty'{Outcome {Dict $d 'Clear' ([object[]]@())} 'void'};'removeEmpty'{Outcome {Dict $d 'Remove' ([object[]]@($query))} 'void'}};$cursorResults=@();foreach($c in $cursors){$cursorResults+=@([ordered]@{current=(Current $c);move=(Outcome {Cursor $c 'MoveNext'} 'bool');reset=(Outcome {Cursor $c 'Reset'} 'void')})};$steps+=@([ordered]@{operation=$operation;result=$result;count=(Dict $d 'get_Count' ([object[]]@()));contents=(Contents $d);beforeMoves=$before;cursors=$cursorResults});$calls++}
 $profiles.Add([ordered]@{stored=$s;query=$q;storedTag=$storedTag;queryTag=$queryTag;initial=$initial;steps=$steps})
}}
if($profiles.Count -ne 1024 -or $calls -ne 8192){throw 'Wrong floating equality matrix'}
$record=[ordered]@{schemaVersion=1;runtimeVersion=[Environment]::Version.ToString();coreLibSha256=$coreHash;oracleSha256=(Get-FileHash -LiteralPath $PSCommandPath -Algorithm SHA256).Hash.ToLowerInvariant();planSha256=(Get-FileHash -LiteralPath $PlanPath -Algorithm SHA256).Hash.ToLowerInvariant();culture='Invariant';profiles=$profiles.ToArray();nativeOperations=$calls;qualification='SELECTED_FLOAT_DOUBLE_KEY_EQUALITY_AND_MUTATION_ONLY; FULL_BOXING_CULTURE_HARDWARE_ABI_SERIALIZATION_AND_TASK_ACCEPTANCE_OPEN'};[IO.File]::WriteAllText($OutputPath,($record|ConvertTo-Json -Depth 20 -Compress)+"`n",[Text.UTF8Encoding]::new($false));Write-Output 'PASS floating key native matrix: 1024 profiles, 8192 operations'
